package com.cob.emr.ddd.domain.medicalnote.model.assessment;import com.cob.emr.ddd.domain.medicalnote.model.valueobjects.*;import lombok.Builder;import lombok.Getter;import java.util.List;import java.util.stream.Collectors;@Getter@Builder(toBuilder = true)public class ClinicalAssessment {        private final PatientPresentation patientPresentation;    private final List<Problem> problemList;    private final List<FunctionalGoal> goals;    private final Diagnosis diagnosis;    private final RehabilitationPotential rehabilitationPotential;    private final PatientCompliance patientCompliance;    private final Contraindications contraindications;    private final ConsentToCare consentToCare;    private final String patientEducation;    private final String reasonForAssessment;        public void validate() {        if (goals == null || goals.isEmpty()) {            throw new IllegalStateException("At least one goal is required");        }                if (rehabilitationPotential == null) {            throw new IllegalStateException("Rehabilitation potential is required");        }                goals.forEach(FunctionalGoal::validate);    }        public boolean hasGoals() {        return goals != null && !goals.isEmpty();    }        public ClinicalAssessment clearDiagnosisForFollowUp() {        return this.toBuilder()            .diagnosis(null)            .build();    }        public double calculateOverallProgress() {        if (goals == null || goals.isEmpty()) return 0.0;                return goals.stream()            .mapToInt(goal -> parseProgressPercentage(goal.getMet()))            .average()            .orElse(0.0);    }        public boolean isPatientProgressing() {        return calculateOverallProgress() >= 50.0;    }        public boolean isReadyForDischarge() {        long metGoals = goals.stream()            .filter(goal -> parseProgressPercentage(goal.getMet()) >= 80)            .count();        return metGoals >= (goals.size() * 0.8);    }        public List<FunctionalGoal> getUnmetGoals() {        if (goals == null) return List.of();        return goals.stream()            .filter(goal -> parseProgressPercentage(goal.getMet()) < 80)            .collect(Collectors.toList());    }        private int parseProgressPercentage(String met) {        if (met == null || met.trim().isEmpty()) return 0;        try {            String cleaned = met.replace("%", "").trim();            return Integer.parseInt(cleaned);        } catch (NumberFormatException e) {            return 0;        }    }}
